// ─── Prediction Helper ────────────────────────────────
int rf_predict(float* input, float* confidence) {
    float output[5];
    score(input, output);

    // Convert votes to probabilities
    float total = 0.0f;
    for (int i = 0; i < 5; i++) total += output[i];

    int best = 0;
    float best_prob = 0.0f;
    for (int i = 0; i < 5; i++) {
        float prob = (total > 0.0f) ? output[i] / total : 0.0f;
        if (prob > best_prob) {
            best_prob = prob;
            best = i;
        }
    }
    *confidence = best_prob;
    return best;
}

